using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using MySqlConnector;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class ProfissionaisController:Controller {private readonly Db _db;public ProfissionaisController(Db db)=>_db=db;public IActionResult Index(){var l=new List<Profissional>();using var x=_db.Open();using var c=new MySqlCommand("SELECT * FROM profissional ORDER BY nome",x);using var r=c.ExecuteReader();while(r.Read())l.Add(new Profissional{Id=r.GetInt32("id"),Nome=r.GetString("nome"),RegistroProfissional=r.GetString("registro_profissional"),Especialidade=r.GetString("especialidade"),Status=r.GetString("status")});return View(l);}[HttpGet]public IActionResult Create()=>View(new Profissional{Status="ativo"});[HttpPost][ValidateAntiForgeryToken]public IActionResult Create(Profissional p){using var x=_db.Open();using var c=new MySqlCommand("INSERT INTO profissional(nome,registro_profissional,especialidade,status) VALUES(@n,@r,@e,@s)",x);c.Parameters.AddWithValue("@n",p.Nome);c.Parameters.AddWithValue("@r",p.RegistroProfissional);c.Parameters.AddWithValue("@e",p.Especialidade);c.Parameters.AddWithValue("@s",p.Status??"ativo");try{c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}catch(MySqlException ex){ModelState.AddModelError("",ex.Message);return View(p);}}[HttpPost][ValidateAntiForgeryToken]public IActionResult Delete(int id){using var x=_db.Open();using var c=new MySqlCommand("DELETE FROM profissional WHERE id=@id",x);c.Parameters.AddWithValue("@id",id);c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}}
